 mods=[
 ('How exchange works', 'A rate says how much of one currency you get for another.', ['Quote like EUR 1 = INR 90 means 1 euro buys 90 rupees.', 'Mid-market rate is the middle of buy and sell prices.', 'Providers add a spread and fees.', 'Rates move every second.'], 'Mid-market 1 EUR = 90.00 INR. Provider offers 88.20: spread = (90 - 88.2) / 90 = 2%.', 'Convert five amounts in both directions.', 'All conversions correct with currency shown.'),
 ('True cost', 'The advertised rate is not the whole price.', ['True cost = (mid-market value - what receiver gets) / mid-market value.', 'Add fixed fees, card fees and receiver bank fees.', 'Compare same amount, same day.', 'Watch for "zero fee" offers with poor rates.'], 'Send EUR 500: mid value INR 45,000. Receiver gets INR 43,900 after a 3 EUR fee and 1.8% spread. True cost = 1,100 / 45,000 = 2.4%.', 'Calculate true cost for three real quotes.', 'Percentages correct.'),
 ('Comparing routes', 'Bank, card, cash, online provider, wallet: each has trade-offs.', ['Cost, speed, limits, safety, convenience.', 'Public comparison tools and their limits.', 'Time of day and weekends.', 'Who regulates each route.'], 'Bank wire: 3 days, 3.5%. Online provider: 1 day, 1.4%. Cash agent: instant, 4%.', 'Build a five-route comparison table.', 'Table has all five measures.'),
 ('Safety and scams', 'Exchange attracts fraud.', ['Fake rates too good to be true; pressure to act now.', 'Unlicensed providers; checks on the regulator\'s public list.', 'Never send money to personal accounts for a "business".', 'Keep records of every transfer.'], 'An offer promises a rate 8% above market: reject it; check the public register; report if fake.', 'Complete a scam checklist on three adverts.', 'Red flags named for each.'),
 ('Rules and duties', 'Providers must follow identity and anti-crime rules.', ['Licence, identity checks, limits and reports.', 'Record-keeping periods.', 'Taxes and declared limits at borders.', 'Consumer protection and complaints routes.'], 'A provider asks for ID above a set amount: that is a legal duty, not an insult.', 'Summarise the rules for your place in one page.', 'Page names the regulator and key limits.'),
 ('Design a transparent display', 'Show the total before the customer commits.', ['Show mid-market rate, our rate, fee and total received.', 'Show the time to arrive.', 'Lock the rate for a short time and say how long.', 'Show how to complain.'], 'Screen: "You send EUR 500. Mid-market 90.00. Our rate 89.10. Fee EUR 3. You get INR 44,247. Rate held 5 minutes."', 'Sketch the price screen.', 'Every number labelled with currency.'),
 ('Risk plan', 'Rates move and systems fail.', ['Rate risk: hold time and limits.', 'Operational risk: down time and wrong entries.', 'Fraud risk: checks and limits.', 'Liquidity: having enough of each currency.'], 'A rate falls 1.5% during a 10-minute delay: the price lock protects the customer and a limit protects the business.', 'Write a risk table with six rows.', 'Each row has a control and an owner.'),
 ('Present and plan', 'Explain the concept clearly and honestly.', ['One page: need, routes compared, display, risks, rules.', 'State what is concept only.', 'Gather feedback from a trader or traveller.', 'Plan 90 days: licence path, advisers.'], 'Feedback: "Show total in rupees first." Change made and retested.', 'Present to peers and mentor.', 'Feedback recorded and applied.')],
 quiz=[('What is a spread?', 'The gap between mid-market and the rate you are offered.'), ('Calculate true cost.', '(Mid-market value minus received) divided by mid-market value.'), ('Why compare the same day?', 'Rates change constantly.'), ('Red flag in an offer?', 'A rate far better than the market or pressure to hurry.'), ('Why are ID checks needed?', 'Legal duties to prevent crime.'), ('What should a display show?', 'Rate, fee, total received, time and complaint route.'), ('What is rate risk?', 'The rate moves before the deal completes.'), ('What does "zero fee" hide?', 'Possibly a poor rate.'), ('May this course hold real money?', 'No, concepts only.'), ('Where to check licences?', 'The regulator\'s public register.')],
 rubric=[('Calculations', 'True cost correct for five routes', 'Sensitivity to rate change shown'), ('Comparison', 'Five measures per route', 'Recommendation matched to user need'), ('Safety', 'Scam checklist used', 'Reports on suspicious ads'), ('Design', 'Transparent display drafted', 'Users understand it in 10 seconds'), ('Rules awareness', 'Regulator and limits named', 'Licence path outlined')],
